SELECT d.volume_id,d.document_id,dd.date_iso,substr(d.header,1,90) FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid LEFT JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE frus_documents MATCH '"Tongsun Park" OR Koreagate' AND d.is_front_matter=0 AND d.is_editorial_note=0 ORDER BY dd.date_iso;
SELECT 'pre1860 total non-apparatus dated docs', COUNT(*) FROM document_cache d JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE d.is_front_matter=0 AND d.is_editorial_note=0 AND dd.date_iso<'1860-01-01' AND dd.date_iso<>'';
SELECT 'pre1860 volumes', COUNT(DISTINCT d.volume_id) FROM document_cache d JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE d.is_front_matter=0 AND d.is_editorial_note=0 AND dd.date_iso<'1860-01-01' AND dd.date_iso<>'';
SELECT 'pre1860 DeptState (positive control)', COUNT(*) FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE frus_documents MATCH '"Department of State"' AND d.is_front_matter=0 AND d.is_editorial_note=0 AND dd.date_iso<'1860-01-01' AND dd.date_iso<>'';
SELECT 'pre1860 ZZZ (negative control)', COUNT(*) FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE frus_documents MATCH 'ZZZ_IMPOSSIBLE_ZZZ' AND d.is_front_matter=0 AND d.is_editorial_note=0 AND dd.date_iso<'1860-01-01' AND dd.date_iso<>'';
SELECT 'pre1860 corruption-family+counterpart vocabulary', COUNT(*) FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id WHERE frus_documents MATCH 'corrupt OR bribe OR bribery OR peculation OR defalcation OR extortion OR exactions OR embezzle OR malversation OR venal OR "presents to" OR squeeze OR irregularities' AND d.is_front_matter=0 AND d.is_editorial_note=0 AND dd.date_iso<'1860-01-01' AND dd.date_iso<>'';
